import React from 'react'
import { useDataLayerValue } from '../DataLayer'

function Content({data}) {

    const [{page},dispatch] = useDataLayerValue();

    const mainPage = () => {
        dispatch({
          type: "SET_PAGE",
          page: "main",
        });
      }

    return (
        <div>
            <h1 onClick={mainPage}>back</h1>
            <div className={"grid grid-cols-3 gap-4"} >
                <div className={"col-span-2"}>
                    <div className={"place-content-center flex flex-wrap"} >
                        <img className={"w-2/3 h-2/3 object-contain self-center"} src={data.large} ></img>
                    </div>
                </div>
                <div className={"col-span-1"}>
                    <div className={"place-content-center flex-wrap"} >
                        <div className={"w-4 h-4 bg-black flex"}>

                        </div>
                    </div>
                </div>
            </div>
        </div>
    )
}

export default Content
